var i=[{title:`Warum Gewohnheiten wichtig sind`,text:`Kraft, Herz-Kreislauf-Leistung und Bewegungsgeschick entwickeln sich durch wiederholtes Üben. Ein Training, das auf dem Papier großartig aussieht, nützt nichts, wenn es zu lang, unpraktisch oder unangenehm zum Wiederholen ist. Damit sind Häufigkeit und Dranbleiben Teil der Programmgestaltung und nicht nur eine Frage der Motivation.`},{title:`Training an einen Auslöser koppeln`,text:`Verknüpfe das Training mit etwas, das ohnehin passiert, oder mit einem festen Termin: „Nach der Arbeit am Montag und Donnerstag mache ich meine 25-Minuten-Einheit.“ Lege Kleidung, Platz oder Ausrüstung vorher bereit. Mache den ersten Schritt winzig, etwa die Schuhe anzuziehen und ein fünfminütiges Aufwärmen zu beginnen, damit du nicht von Begeisterung abhängst.`},{title:`Eine Mindesteinheit haben`,text:`An einem vollen Tag können eine Kniebeugen-Variante, eine Druck- oder Zugübung und ein kurzer Spaziergang die Gewohnheit am Leben halten. Das Minimum ist kein dauerhafter Ersatz für progressives Training. Seine Aufgabe ist es zu verhindern, dass aus einem verpassten Tag mehrere verpasste Wochen werden. Halte fest, was du wirklich getan hast, und trage ein verkürztes Training nicht als vollständig ein.`},{title:`Rückschläge gelassen nehmen`,text:`Eine verpasste Einheit löscht deine früheren Anpassungen nicht aus. Mache mit dem nächsten geplanten Training weiter und verdopple die Arbeit nicht, um verpasstes Training „nachzuholen“. Verringere nach Krankheit, starker Erschöpfung oder einer langen Pause Intensität und Umfang, bis deine gewohnte Belastbarkeit zurückkehrt.`},{title:`Dein Umfeld prüfen`,text:`Schlechter Schlaf, ein umständlicher Weg ins Fitnessstudio, Ausrüstung, an die du nicht herankommst, und zu lange Einheiten können alle die Regelmäßigkeit untergraben. Diese zu beheben hilft möglicherweise mehr, als eine neue Übung zu finden. Freude am Training und die eigene Wahl machen eine Routine ebenfalls leichter durchzuhalten.`},{title:`TrainUp nutzen`,text:`Lege im Profil eine realistische Anzahl an Trainingstagen und deine bevorzugten Tage fest und gib deinen Platz und deine Ausrüstung an, damit der Plan nur passende Übungen wählt. Erinnerungen an Trainings auf der Seite „Heute“ können dein Auslöser sein. Der Verlauf zeigt die Trainings dieser Woche und deine Gesamtzahl, und der Fortschritt zählt über viele Wochen, du brauchst also keine perfekte Serie.`}];var t=[{label:`CDC: Gewohnheiten und Planung für Aktivität`,url:`https://www.cdc.gov/healthy-weight-growth/physical-activity/getting-started.html`},{label:`WHO: Empfehlungen zur Aktivität`,url:`https://www.who.int/europe/news-room/fact-sheets/item/physical-activity`}];var r={sections:i,sources:t};export{r as default,i as sections,t as sources};